import{_ as e,o as d,c as a,O as r}from"./chunks/framework.e5e2ee33.js";const b=JSON.parse('{"title":".stknds File Format Specified","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"spec/formats/stknds.md","filePath":"spec/formats/stknds.md"}'),i={name:"spec/formats/stknds.md"};function s(n,t,o,l,h,c){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="stknds-file-format-specified" tabindex="-1">.stknds File Format Specified <a class="header-anchor" href="#stknds-file-format-specified" aria-label="Permalink to &quot;.stknds File Format Specified&quot;">​</a></h1><p>This specification is valid for SN versions &lt;= 423.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The .stknds format is compressed when saved and decompressed when loaded to reduce its file size. It is compressed and decompressed using the GZIP compression and decompression algorithms with a buffer size of 4096. The following information assumes that the .stknds file is in its uncompressed state.</p></div><h2 id="metadata" tabindex="-1">Metadata <a class="header-anchor" href="#metadata" aria-label="Permalink to &quot;Metadata&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>Any</td><td>Any</td><td>Stick Nodes version number</td></tr><tr><td>32-bit signed int big-endian</td><td>&gt;=401</td><td>Any</td><td>Build number</td></tr><tr><td>32-bit signed int big-endian</td><td>Any</td><td>Any</td><td><span style="color:coral;">A</span> = Length of project name (prob causes weird behavior or error if length of project name length is &lt;= 0)</td></tr><tr><td>sequence with size of <span style="color:coral;">A</span> of text bytes</td><td>Any</td><td>Any</td><td>Project name</td></tr></tbody></table><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>8-bit unsigned byte</td><td>&gt;=401</td><td>&gt;=16</td><td>Is YouTube short boolean</td></tr><tr><td>8-bit unsigned byte</td><td>&gt;=244</td><td>Any</td><td>Watermark enabled boolean</td></tr><tr><td>32-bit signed int big-endian</td><td>&gt;=220</td><td>Any</td><td><span style="color:coral;">B</span> = Length of watermark text (watermark text bytes are not read if this is &lt;= 0)</td></tr><tr><td>sequence with size of <span style="color:coral;">B</span> of text bytes</td><td>&gt;=220</td><td>Any</td><td>Watermark text</td></tr><tr><td>32-bit signed int big-endian</td><td>&gt;=220</td><td>Any</td><td>Watermark color. See <a href="/sticknodes_spec/spec/subformats/color.html">Color</a> for more information.</td></tr><tr><td>32-bit signed int big-endian</td><td>Any</td><td>Any</td><td>FPS</td></tr><tr><td>32-bit signed int big-endian</td><td>&gt;=176</td><td>Any</td><td>Number of tweened frames</td></tr><tr><td>8-bit unsigned byte</td><td>&gt;=127</td><td>Any</td><td>Has shown loop message boolean</td></tr><tr><td>8-bit unsigned byte</td><td>&gt;=113</td><td>Any</td><td>Has shown panning mode message boolean</td></tr><tr><td>8-bit unsigned byte</td><td>Any</td><td>Any</td><td>Has shown tweening mode message boolean</td></tr><tr><td>8-bit unsigned byte</td><td>&gt;=220</td><td>Any</td><td>Has shown magnifier message boolean</td></tr><tr><td>8-bit unsigned byte</td><td>Any</td><td>Any</td><td>Tweening enabled boolean</td></tr><tr><td>8-bit unsigned byte</td><td>&gt;=127</td><td>Any</td><td>Is loop boolean</td></tr><tr><td>8-bit unsigned byte</td><td>&gt;=140 &amp;&amp; &lt; 200</td><td>Any</td><td>[empty byte]</td></tr></tbody></table><h2 id="unique-ids" tabindex="-1">Unique IDs <a class="header-anchor" href="#unique-ids" aria-label="Permalink to &quot;Unique IDs&quot;">​</a></h2><p>Probably used to keep track of the last assigned unique ID(?)</p><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>Any</td><td>Any</td><td>Unique figure ID</td></tr><tr><td>32-bit signed int big-endian</td><td>&gt;=176</td><td>Any</td><td>Unique textfield box ID</td></tr><tr><td>32-bit signed int big-endian</td><td>&gt;=300</td><td>Any</td><td>Unique movieclip ID</td></tr><tr><td>32-bit signed int big-endian</td><td>&gt;=300</td><td>Any</td><td>Frames container UID</td></tr></tbody></table><h2 id="fonts" tabindex="-1">Fonts <a class="header-anchor" href="#fonts" aria-label="Permalink to &quot;Fonts&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>&gt;=400</td><td>Any</td><td><span style="color:coral;">C</span> = Number of fonts to check if loaded? Does NOT include the default font. Should be equal to whatever the greatest index of all loaded fonts is.</td></tr><tr><td>sequence with size of <span style="color:coral;">C</span> of 8-bit unsigned bytes (booleans)</td><td>&gt;=400</td><td>Any</td><td>Loaded fonts booleans. See <a href="/sticknodes_spec/spec/additional_information/font_booleans.html">font booleans reference</a> for the order of the booleans. Do NOT write a boolean for font index 0 (the default font)</td></tr></tbody></table><h2 id="hidden-stickfigure-library-ids" tabindex="-1">Hidden Stickfigure Library IDs <a class="header-anchor" href="#hidden-stickfigure-library-ids" aria-label="Permalink to &quot;Hidden Stickfigure Library IDs&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>&gt;=300</td><td>Any</td><td><span style="color:coral;">D</span> = Number of hidden stickfigure library IDs</td></tr><tr><td>sequence with size of <span style="color:coral;">D</span> of 32-bit signed int big-endian</td><td>&gt;=300</td><td>Any</td><td>Hidden stickfigure library IDs</td></tr></tbody></table><h2 id="hidden-movieclip-library-ids" tabindex="-1">Hidden Movieclip Library IDs <a class="header-anchor" href="#hidden-movieclip-library-ids" aria-label="Permalink to &quot;Hidden Movieclip Library IDs&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>&gt;=300</td><td>Any</td><td><span style="color:coral;">E</span> = Number of hidden movieclip library IDs</td></tr><tr><td>sequence with size of <span style="color:coral;">E</span> of 32-bit signed int big-endian</td><td>&gt;=300</td><td>Any</td><td>Hidden movieclip library IDs</td></tr></tbody></table><h2 id="hidden-sprite-library-ids" tabindex="-1">Hidden Sprite Library IDs <a class="header-anchor" href="#hidden-sprite-library-ids" aria-label="Permalink to &quot;Hidden Sprite Library IDs&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>&gt;=400</td><td>Any</td><td><span style="color:coral;">F</span> = Number of hidden sprite library IDs</td></tr><tr><td>sequence with size of <span style="color:coral;">F</span> of 32-bit signed int big-endian</td><td>&gt;=400</td><td>Any</td><td>Hidden sprite library IDs</td></tr></tbody></table><h2 id="id-conversion-maps" tabindex="-1">ID Conversion Maps <a class="header-anchor" href="#id-conversion-maps" aria-label="Permalink to &quot;ID Conversion Maps&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td><a href="/sticknodes_spec/spec/subformats/id_conversion_maps.html">ID Conversion Maps</a></td><td>&gt;=300</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/subformats/id_conversion_maps.html">ID Conversion Maps</a> for more information.</td></tr></tbody></table><h2 id="background-image" tabindex="-1">Background Image <a class="header-anchor" href="#background-image" aria-label="Permalink to &quot;Background Image&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>8-bit unsigned byte</td><td>&gt;=140 &amp;&amp; &lt;400</td><td>Any</td><td>Background image enabled boolean</td></tr><tr><td>8-bit unsigned byte</td><td>&gt;=140 &amp;&amp; &lt;170</td><td>Any</td><td>Some boolean related to bg image scaling? Something vaguely related to being strict 1920x1080 when false and scaling to canvas width and height when true?</td></tr><tr><td>32-bit float big-endian</td><td>&gt;=170 &amp;&amp; &lt;400</td><td>Any</td><td>Scale background image x</td></tr><tr><td>32-bit float big-endian</td><td>&gt;=170 &amp;&amp; &lt;400</td><td>Any</td><td>Scale background image y</td></tr><tr><td>32-bit signed int big-endian</td><td>&gt;=140 &amp;&amp; &lt;400</td><td>Any</td><td><span style="color:coral;">W</span> = Background image width</td></tr><tr><td>32-bit signed int big-endian</td><td>&gt;=140 &amp;&amp; &lt;400</td><td>Any</td><td><span style="color:coral;">H</span> = Background image height</td></tr><tr><td>sequence with size of (<span style="color:coral;">W</span> * <span style="color:coral;">H</span>) of <a href="/sticknodes_spec/spec/subformats/rgb888.html">RGB888</a></td><td>&gt;=140 &amp;&amp; &lt;400</td><td>Any</td><td>Image data</td></tr></tbody></table><h2 id="stickfigure-library" tabindex="-1">Stickfigure Library <a class="header-anchor" href="#stickfigure-library" aria-label="Permalink to &quot;Stickfigure Library&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>Any</td><td>Any</td><td><span style="color:coral;">G</span> = Number of stickfigures in library</td></tr><tr><td>sequence of size <span style="color:coral;">G</span> of <a href="/sticknodes_spec/spec/formats/stknds.html#stickfigure-header">Stickfigure Header</a></td><td>Any</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/formats/stknds.html#stickfigure-header">Stickfigure Header</a> for more information.</td></tr></tbody></table><h2 id="stickfigure-header" tabindex="-1">Stickfigure Header <a class="header-anchor" href="#stickfigure-header" aria-label="Permalink to &quot;Stickfigure Header&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>Any</td><td>Any</td><td><span style="color:coral;">H</span> = Length of stickfigure name</td></tr><tr><td>sequence with size of <span style="color:coral;">H</span> of text bytes</td><td>Any</td><td>Any</td><td>Stickfigure name</td></tr><tr><td><a href="/sticknodes_spec/spec/formats/nodes.html">Stickfigure Data</a></td><td>Any</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/formats/nodes.html">Stickfigure Data</a> for more information.</td></tr></tbody></table><h2 id="sound-library" tabindex="-1">Sound Library <a class="header-anchor" href="#sound-library" aria-label="Permalink to &quot;Sound Library&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>&gt;=160</td><td>Any</td><td><span style="color:coral;">I</span> = Number of sounds</td></tr><tr><td>sequence with size of <span style="color:coral;">I</span> of <a href="/sticknodes_spec/spec/formats/stknds.html#sound-header">Sound Header</a></td><td>&gt;=160</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/formats/stknds.html#sound-header">Sound Header</a> for more information.</td></tr></tbody></table><h2 id="sound-header" tabindex="-1">Sound Header <a class="header-anchor" href="#sound-header" aria-label="Permalink to &quot;Sound Header&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>&gt;=160</td><td>Any</td><td><span style="color:coral;">J</span> = Length of sound name</td></tr><tr><td>sequence with size of <span style="color:coral;">J</span> of text bytes</td><td>&gt;=160</td><td>Any</td><td>Sound name</td></tr></tbody></table><h2 id="sprite-library" tabindex="-1">Sprite Library <a class="header-anchor" href="#sprite-library" aria-label="Permalink to &quot;Sprite Library&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>&gt;=400</td><td>Any</td><td><span style="color:coral;">K</span> = Number of sprites</td></tr><tr><td>sequence with size of <span style="color:coral;">K</span> of <a href="/sticknodes_spec/spec/formats/stknds.html#sprite-header">Sprite Header</a></td><td>&gt;=400</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/formats/stknds.html#sprite-header">Sprite Header</a> for more information</td></tr></tbody></table><h2 id="sprite-header" tabindex="-1">Sprite Header <a class="header-anchor" href="#sprite-header" aria-label="Permalink to &quot;Sprite Header&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>8-bit unsigned byte</td><td>&gt;=400</td><td>Any</td><td><span style="color:lightgreen;">if <span style="color:indianred;">1</span>: </span><br><span style="color:coral;">L</span> = <span style="color:indianred;">sprite group source</span> <span style="color:lightgreen;"><br> else if <span style="color:indianred;">0</span>: </span><br> <span style="color:coral;">L</span> = <span style="color:indianred;">sprite source</span></td></tr><tr><td>32-bit signed int big-endian</td><td>&gt;=400</td><td>Any</td><td><span style="color:coral;">M</span> = Length of sprite name</td></tr><tr><td>sequence with size of <span style="color:coral;">M</span> of text bytes</td><td>&gt;=400</td><td>Any</td><td>Sprite name</td></tr><tr><td><span style="color:lightgreen;">if <span style="color:coral;">L</span></span> == <span style="color:indianred;">sprite group source</span><span style="color:lightgreen;">:</span><br> <a href="/sticknodes_spec/spec/subformats/sprite_group_source.html">Sprite Group Library Data</a><br> <span style="color:lightgreen;">else if <span style="color:coral;">L</span></span> == <span style="color:indianred;">sprite source</span><span style="color:lightgreen;">:</span><br> <a href="/sticknodes_spec/spec/subformats/sprite_source.html">Sprite Library Data</a></td><td>&gt;=400</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/subformats/sprite_group_source.html">Sprite Group Library Data</a> or <a href="/sticknodes_spec/spec/subformats/sprite_source.html">Sprite Library Data</a> for more information.</td></tr></tbody></table><h2 id="movieclip-library" tabindex="-1">Movieclip Library <a class="header-anchor" href="#movieclip-library" aria-label="Permalink to &quot;Movieclip Library&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>&gt;=300</td><td>Any</td><td><span style="color:coral;">N</span> = Number of movieclips</td></tr><tr><td>sequence with size of <span style="color:coral;">N</span> of <a href="/sticknodes_spec/spec/formats/stknds.html#movieclip-header">Movieclip Header</a></td><td>&gt;=300</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/formats/stknds.html#movieclip-header">Movieclip Header</a> for more information.</td></tr></tbody></table><h2 id="movieclip-header" tabindex="-1">Movieclip Header <a class="header-anchor" href="#movieclip-header" aria-label="Permalink to &quot;Movieclip Header&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>&gt;=300</td><td>Any</td><td><span style="color:coral;">O</span> = Length of movieclip name</td></tr><tr><td>sequence with size of <span style="color:coral;">O</span> of text bytes</td><td>&gt;=300</td><td>Any</td><td>Movieclip name</td></tr><tr><td><a href="/sticknodes_spec/spec/subformats/movieclip_library_data.html">Movieclip Library Data</a></td><td>&gt;=300</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/subformats/movieclip_library_data.html">Movieclip Library Data</a> for more information.</td></tr><tr><td>32-bit signed int big-endian</td><td>&gt;=300</td><td>Any</td><td>Movieclip UID</td></tr></tbody></table><h2 id="frames" tabindex="-1">Frames <a class="header-anchor" href="#frames" aria-label="Permalink to &quot;Frames&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>Any</td><td>Any</td><td><span style="color:coral;">P</span> = Number of frames in project</td></tr><tr><td>sequence of <a href="/sticknodes_spec/spec/subformats/frame.html">Frame</a> of length <span style="color:coral;">P</span></td><td>Any</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/subformats/frame.html">Frame</a> for more information.</td></tr></tbody></table><h2 id="auto-camera" tabindex="-1">Auto Camera <a class="header-anchor" href="#auto-camera" aria-label="Permalink to &quot;Auto Camera&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>&gt;=237</td><td>Any</td><td><span style="color:coral;">Q</span> = Number of auto-cams</td></tr><tr><td>sequence with size of <span style="color:coral;">Q</span> of <a href="/sticknodes_spec/spec/subformats/auto_camera.html">Auto Camera</a></td><td>&gt;=237</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/subformats/auto_camera.html">Auto Camera</a> for more information.</td></tr></tbody></table><h2 id="session-save-data" tabindex="-1">Session Save Data <a class="header-anchor" href="#session-save-data" aria-label="Permalink to &quot;Session Save Data&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td><a href="/sticknodes_spec/spec/subformats/session_save_data.html">Session Save Data</a></td><td>&gt;=251</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/subformats/session_save_data.html">Session Save Data</a> for more information.</td></tr></tbody></table><h2 id="movieclip-cache" tabindex="-1">Movieclip Cache <a class="header-anchor" href="#movieclip-cache" aria-label="Permalink to &quot;Movieclip Cache&quot;">​</a></h2><table><thead><tr><th>Data Type</th><th>Versions</th><th>Builds</th><th>Description</th></tr></thead><tbody><tr><td>32-bit signed int big-endian</td><td>&gt;=319</td><td>Any</td><td><span style="color:coral;">R</span> = Number of cached movieclips</td></tr><tr><td>sequence with size of <span style="color:coral;">R</span> of <a href="/sticknodes_spec/spec/subformats/cached_movieclip.html">Cached Movieclip</a></td><td>&gt;=319</td><td>Any</td><td>See <a href="/sticknodes_spec/spec/subformats/cached_movieclip.html">Cached Movieclip</a> for more information.</td></tr></tbody></table>',46)])])}const y=e(i,[["render",s]]);export{b as __pageData,y as default};
